    return `<div class="ts-library-filter-layer"><button class="ts-library-filter-scrim" type="button" data-library-filter-action="close" aria-label="Close filters"></button><section class="ts-library-filter-dialog" role="dialog" aria-modal="true" aria-labelledby="ts-library-filter-title"><header><div><p class="ts-kicker">Browse controls</p><h3 id="ts-library-filter-title">More filters</h3><span>Surface stays visible in the library. Use this sheet only for message compatibility and style-family narrowing.</span></div><button class="ts-btn ts-btn-icon" type="button" data-library-filter-action="close" aria-label="Close filters">\xD7</button></header><div class="ts-library-filter-body"><section><div class="ts-library-filter-label"><strong>Message layout</strong><span>Compatibility, not guesswork</span></div><div class="ts-library-filter-grid ts-library-filter-grid-small"><button type="button" data-library-layout="all" aria-pressed="${this.styleLibraryLayout === "all"}">Any</button><button type="button" data-library-layout="bubble" aria-pressed="${this.styleLibraryLayout === "bubble"}">Bubble</button><button type="button" data-library-layout="minimal" aria-pressed="${this.styleLibraryLayout === "minimal"}">Minimal</button></div></section><section><div class="ts-library-filter-label"><strong>Style family</strong><span>Filters recipe cards only</span></div><div class="ts-library-family-grid"><button type="button" data-library-family="all" aria-pressed="${this.styleLibraryFamily === "all"}">All families</button>${families.map((family) => `<button type="button" data-library-family="${escapeHtml(family)}" aria-pressed="${this.styleLibraryFamily === family}">${escapeHtml(family)}</button>`).join("")}</div></section></div><footer><span>${active ? `${active} active filter${active === 1 ? "" : "s"}` : "No extra filters"}</span><button class="ts-btn" type="button" data-library-filter-action="reset" ${active ? "" : "disabled"}>Clear filters</button><button class="ts-btn ts-btn-primary" type="button" data-library-filter-action="close">Show results</button></footer></section></div>`;
