    root.innerHTML = `${backdrop}<section class="ts-style-library-modal ts-preset-library ts-library-browser" ${modalA11y} aria-labelledby="ts-style-library-title" style="--ts-quick-accent:${escapeHtml(this.quickAccent)};--ts-quick-text:${escapeHtml(this.quickText)};--ts-quick-intensity:${this.quickIntensity / 100}"><header class="ts-style-library-head"><div><p class="ts-kicker">Style library</p><h2 id="ts-style-library-title">${this.styleLibraryView === "my-styles" ? "My Styles" : "Browse looks"}</h2><span>${this.styleLibraryView === "my-styles" ? "Reusable semantic looks you saved yourself. Apply them across theme projects without copying CSS." : "Packs are collections. Styles are the pieces. Search the warehouse without wearing the inventory terminal as a hat."}</span></div><div class="ts-style-library-head-actions">${this.renderStyleLibraryPresentationButton()}<button class="ts-btn ts-btn-icon" type="button" data-library-action="close" aria-label="Close style library">\xD7</button></div></header><div class="ts-library-workspace"><aside class="ts-library-sidebar"><nav class="ts-library-view-nav" aria-label="Library view">${viewTabs}</nav><section class="ts-library-side-status"><span class="ts-kicker">${escapeHtml(viewLabels[this.styleLibraryView])}</span><strong data-library-result-count>${escapeHtml(totalCopy)}</strong><p>${this.styleLibraryView === "browse" ? "Explore packs and individual styles." : this.styleLibraryView === "recent" ? "Things you touched lately." : this.styleLibraryView === "applied" ? "Layers currently contributing." : this.styleLibraryView === "my-styles" ? "Reusable looks you authored yourself." : "Your saved fashion crimes."}</p></section><details class="ts-library-tune"><summary><div><strong>Tune previews</strong><span><i style="--swatch:${escapeHtml(this.quickAccent)}"></i><i style="--swatch:${escapeHtml(this.quickText)}"></i>${this.quickIntensity}%</span></div><b>\u2304</b></summary><div class="ts-library-tune-body">${this.renderQuickPalette()}</div></details></aside><section class="ts-library-results${this.styleLibraryMobileBrowseCollapsed ? " is-mobile-browse-collapsed" : ""}"><button class="ts-library-mobile-browse-toggle" type="button" data-library-action="mobile-browse-toggle" aria-expanded="${!this.styleLibraryMobileBrowseCollapsed}"><span><small>Browse controls</small><strong>${this.styleLibraryView === "my-styles" ? "My Styles" : this.styleLibraryArea === "all" ? "All styles" : escapeHtml(STYLE_LIBRARY_AREAS.find((entry) => entry.id === this.styleLibraryArea)?.label ?? "Styles")}</strong></span><b aria-hidden="true">\u2304</b></button><div class="ts-library-results-toolbar"><div class="ts-library-results-title"><div class="ts-library-results-heading"><span class="ts-kicker">${escapeHtml(viewLabels[this.styleLibraryView])}</span><strong>${this.styleLibraryView === "my-styles" ? "Saved by you" : this.styleLibraryArea === "all" ? "All styles" : escapeHtml(STYLE_LIBRARY_AREAS.find((entry) => entry.id === this.styleLibraryArea)?.label ?? "Styles")}</strong></div>${this.styleLibraryView === "my-styles" ? "" : `<nav class="ts-library-surface-nav" aria-label="Library surface">${surfaceTabs}</nav>`}<span data-library-result-count>${escapeHtml(totalCopy)}</span></div><div class="ts-library-search-row"><label class="ts-library-search"><span>Search library</span><input class="ts-search" type="search" value="${escapeHtml(this.styleLibraryQuery)}" placeholder="${this.styleLibraryView === "my-styles" ? "Search your saved styles\u2026" : "minimal portrait, manga heading, glass composer\u2026"}" data-library-search></label>${this.styleLibraryView === "my-styles" ? "" : `<button class="ts-library-pack-owned-toggle" type="button" data-library-pack-owned aria-pressed="${this.styleLibraryShowPackOwned}" title="${this.styleLibraryShowPackOwned ? "Hide" : "Show"} individual styles that also belong to a pack"><span class="ts-library-toggle-track" aria-hidden="true"><i></i></span><span>Show pack-owned</span></button><button class="ts-btn ts-library-filter-trigger" type="button" data-library-filter-action="open" aria-expanded="${this.styleLibraryFiltersOpen}">More filters${activeFilters ? `<span>${activeFilters}</span>` : ""}</button>`}</div>${filterChips && this.styleLibraryView !== "my-styles" ? `<div class="ts-library-active-filters"><span>Extra filters</span>${filterChips}<button type="button" data-library-filter-action="reset">Clear all</button></div>` : ""}</div><main class="ts-style-library-scroll">${this.styleLibraryView === "my-styles" ? savedStyles.length ? `<section class="ts-library-group ts-saved-style-group"><div class="ts-library-group-head"><div><strong>My Styles</strong><small>Cross-project semantic styles \xB7 apply without copying CSS</small></div><span>${savedStyles.length}</span></div><div class="ts-saved-style-grid">${savedStyles.map((style) => this.renderSavedStyleCard(style)).join("")}</div></section>` : `<div class="ts-library-empty"><strong>Nothing saved yet.</strong><span>${escapeHtml(emptyCopy)}</span></div>` : `${layoutNote}${composerWorkshop}${packs.length ? `<section class="ts-library-group ts-pack-group"><div class="ts-library-group-head"><div><strong>Packs</strong><small>Coordinated collections \xB7 open before applying</small></div><span>${packs.length}</span></div><div class="ts-pack-grid">${packs.map((entry) => this.renderPackCard(entry)).join("")}</div></section>` : ""}${groups.length ? groups.map((group) => `<section class="ts-library-group"><div class="ts-library-group-head"><div><strong>${escapeHtml(group.label)}</strong><small>Individual styles \xB7 apply here or pencil into Design</small></div><span>${group.entries.length}</span></div>${this.renderPresetCards(group.entries.map((entry) => entry.preset), { library: true })}</section>`).join("") : !packs.length ? `<div class="ts-library-empty"><strong>Nothing here yet.</strong><span>${escapeHtml(emptyCopy)}</span></div>` : ""}`}</main></section></div>${this.renderStyleLibraryFilterDialog(families)}</section>`;
    this.bindStyleLibrary();
    const composerSidecar = root.querySelector(".ts-composer-workshop-sidecar");
