      if (this.composerWorkshopRole === "input.actionbar" && this.selection && activeScope(this.selection).selector.includes("[data-composer-action=")) {
        this.composerWorkshopRole = null;
        this.leaveStyleLibraryForDesign();
        this.workspace = "design";
        this.render();
        return;
      }
      this.openKnownRoleInDesign(this.composerWorkshopRole);
